// build/replay_tb.v -- C1: replay the reference stimulus into puzzle.v.
//
// Generated by tools/puzzle/simulate.py (plan step C1). Do not edit by hand.
// Regenerate with:  python -m tools.puzzle vcd-replay
// Compile with:     iverilog -g2012 -o replay.vvp build/replay_tb.v puzzle.v build/cells.v
//
// The stimulus below is not authored. It is the change list parsed out of
// asic-puzzle-2026/example_inputs.vcd
//   sha256 2247ae1c1195322616e9ac81dbfccb5b84c9994b96c28f1a106c2100a7bcbe2e
// replayed at the same instants (95 changes on rst_n/enable/I, all of them
// on falling edges). The one thing not transcribed is the clock, because it is the one
// thing that can be asserted: 625 edges, every one 5000 ps apart, first
// rise at 5000 ps -- so `always #5000` reproduces it exactly, and
// tools/checks/check_stepC1.py re-checks that uniformity against the file itself.
//
// Sampling: 1 ps after each rising edge, the instant the reference
// dumps -- the register state after the edge, with the stimulus held across the cycle.
// 312 cycles are printed, one line each, as
//   C <cycle> <rst_n> <enable> <I> <O[7:0]> <success> [<probe>...]
//
// Usage:  vvp replay.vvp [+force=0|1]
//   +force=<v>  forces each undriven net to <v> for the whole run, to test whether it
//               can move an output at all. Without it nothing is forced.
// =============================================================================

`timescale 1ps/1ps

module replay_tb;
  localparam integer CYCLES = 312;
  localparam integer SAMPLE_DELAY_PS = 1;

  reg clk = 1'b0;
  reg rst_n = 1'b0;
  reg enable = 1'b0;
  reg I = 1'b0;
  wire [7:0] O;
  wire success;
  integer cyc = 0;
  integer force_arg;
  reg force_bit = 1'b0;

  // VGND/VPWR are declared inout on the netlist, so they have to be driven through a
  // net that supports continuous assignment rather than tied to a literal expression.
  wire VGND;
  wire VPWR;
  assign VGND = 1'b0;
  assign VPWR = 1'b1;

  puzzle dut (.clk(clk), .rst_n(rst_n), .enable(enable), .I(I),
              .O(O), .success(success), .VGND(VGND), .VPWR(VPWR));

  // The reference clock: 625 edges, 5000 ps half period, first rise at
  // 5000 ps.
  always #5000 clk = ~clk;

  // The reference stimulus, one line per instant that something changed.
  initial begin
    if ($value$plusargs("force=%d", force_arg)) begin
      force_bit = force_arg[0];
      force dut.n806 = force_bit;
      $display("F %s forced = %b", "n806", force_bit);
    end
    #30000 rst_n = 1'b1;
    #10000 enable = 1'b1;
    #20000 I = 1'b1;
    #10000 I = 1'b0;
    #10000 I = 1'b1;
    #10000 I = 1'b0;
    #10000 I = 1'b1;
