    #40000 enable = 1'b0;
    #310000 rst_n = 1'b0;
    #30000 rst_n = 1'b1;
    #10000 I = 1'b1; enable = 1'b1;
    #20000 I = 1'b0;
    #10000 I = 1'b1;
