    #10000 I = 1'b0;
    #50000 enable = 1'b0;
  end

  // Sample one time step after every rising edge, for as many cycles as the reference has.
  always @(posedge clk) begin
    #1;
    $display("C %0d %b %b %b %b %b %b", cyc, rst_n, enable, I, O, success, dut.n806);
    cyc = cyc + 1;
    if (cyc >= CYCLES) $finish;
  end
endmodule
